/**
 * dsh-notifier events 域 —— 订阅宿主事件、转交翻译、把请求递给下游。
 * 本块只做搬运不含判断；状态机的装配与卸载也在这里成对发生。
 */
import type { EventsDeps, PipelinePort } from "../../deps.ts";
import { agentStates } from "../state/index.ts";
import {
  translateAgentDisposed,
  translateAgentError,
  translateAgentStatus,
  translateApproval,
  translateSessionEvent,
  translateTurnStopping,
  translateUserQuestion,
} from "../translate/index.ts";
import type { Translation } from "../translate/type.ts";

/** 宿主事件的订阅集合：装配时装上，卸载时全部摘除。 */
class EventListener {
  /** 是否已装配；单例实例重复装配是编程错误，当场暴露。 */
  private installed = false;
  /** 退订句柄；卸载期逐个调用。 */
  private readonly releases: Array<() => void> = [];

  /** 装配：装状态机，再订阅宿主事件。 */
  install(deps: EventsDeps): void {
    if (this.installed) throw new Error("dsh-notifier: events 域只能装配一次");
    this.installed = true;
    agentStates.install({ logger: deps.logger, agents: deps.agents });
    const { events: port, pipeline } = deps;
    this.releases.push(
      port.onApprovalRequest((request) => forward(pipeline, translateApproval(request))),
      port.onUserQuestion((request) => forward(pipeline, translateUserQuestion(request))),
      port.onSessionEvent((sessionId, event) =>
        forward(pipeline, translateSessionEvent(sessionId, event)),
      ),
      // agent 四个事件把官方载荷整份转给翻译：翻出哪一类通知要看会话日志、header 与
      // turn 证据，这些都在载荷里的 Agent 对象上，本块不做拆分。
      port.onAgentStatus((payload) => forward(pipeline, translateAgentStatus(payload))),
      port.onAgentDisposed((payload) => forward(pipeline, translateAgentDisposed(payload))),
      port.onAgentTurnStopping((payload) => forward(pipeline, translateTurnStopping(payload))),
      port.onAgentError((payload) => forward(pipeline, translateAgentError(payload))),
    );
  }

  /** 摘除全部订阅并卸载状态机。重复调用无害——卸载链可能走到不止一次。 */
  release(): void {
    for (const release of this.releases) release();
    this.releases.length = 0;
    agentStates.release();
    // 复位而不是只摘订阅：留着会让同进程的下一次 `install` 撞上「只能装配一次」。
    this.installed = false;
  }
}

/** 把翻译结果递给下游；不产出通知是常态，不是需要处理的情况。 */
function forward(pipeline: PipelinePort, translation: Translation): void {
  if (translation.ok) pipeline.submit(translation.request);
}

/** 本域唯一的订阅点：类不外放，外面 `new` 不出第二份订阅。 */
export const eventListener = new EventListener();

/**
 * dsh-notifier events 域 —— 会话日志读取与子代理归属判定（只读宿主对象，不改写）。
 * payload 跨宿主边界不受信，读取一律防御性收窄。
 */
import type { Agent } from "@deepseek-ai/dsh-agent";
// 会话标题事件由该插件并入 `SessionEventMap`：不引它，`session/title` 就不在日志类型里。
import type {} from "@deepseek-ai/dsh-session-title";
import type { SessionEvent } from "@deepseek-ai/dsh-session";
import type { TurnEndReason } from "@deepseek-ai/dsh-session/types";
import type { AgentRegistryPort } from "../../deps.ts";
import type { SessionTitle, TurnEndRead } from "./type.ts";

/** 会话标题的展示上限；模板拼接与任务名共用这一个数字。 */
const TITLE_LIMIT = 40;

/** 会话标题：日志里最后一个 `session/title`，trim 后截断 40 字符。 */
export function sessionTitleOf(agent: Agent): SessionTitle {
  try {
    // eslint-disable-next-line sonarjs/deprecation -- 0.1.7-rc.1 起 snapshotEvents 标 @deprecated（rc.2 沿用）（本仓规则名见 tools/lint/eslint.config.js，上游同位置 oxlint-disable）：同步快照读法在迁移前保留，测试 5 处不动（P2）。
    const events = agent.session.snapshotEvents();
    for (let i = events.length - 1; i >= 0; i -= 1) {
      const event = events[i];
      if (event.type !== "session/title") continue;
      const title = event.data.title.trim();
      if (title.length === 0) return { found: false };
      return { found: true, title: title.slice(0, TITLE_LIMIT) };
    }
  } catch {
    // 日志读不出来不影响通知主流程
  }
  return { found: false };
}

/**
 * 从一条会话事件里读 turn 证据；`turn` 非有限数必须跳过——返回 NaN 会被完成判定当成合法
 * 证据推进，此后真实完成因 `x > NaN` 恒为假被永久吞掉。
 */
export function turnEndEvidenceOf(event: SessionEvent): TurnEndRead {
  if (event.type !== "turn/end") return { found: false };
  const reason = event.data.reason;
  if (typeof reason !== "object" || reason === null) return { found: false };
  const turn = event.data.turn;
  if (!Number.isFinite(turn)) return { found: false };
  return { found: true, evidence: { turn, kind: readTurnKind(reason) } };
}

/** 日志里最新一条 `turn/end`；倒序扫，因为 `turn/end` 之后可能尾随别的追加。 */
export function lastTurnEndOf(agent: Agent): TurnEndRead {
  try {
    // eslint-disable-next-line sonarjs/deprecation -- 0.1.7-rc.1 起 snapshotEvents 标 @deprecated（rc.2 沿用）（本仓规则名见 tools/lint/eslint.config.js，上游同位置 oxlint-disable）：同步快照读法在迁移前保留，测试 5 处不动（P2）。
    const events = agent.session.snapshotEvents();
    for (let i = events.length - 1; i >= 0; i -= 1) {
      const read = turnEndEvidenceOf(events[i]);
      if (read.found) return read;
    }
  } catch {
    // 日志读不出来不影响通知主流程
  }
  return { found: false };
}

/**
 * 是否子代理：`origin` 命中即真；否则要运行时归属确凿成立（父 agent 在活体注册表里，
 * 且确由它创建）。任一环不成立都走主任务分支——宁可多报一条 done，不静默用户自己的任务。
 */
export function isSubagentOf(agent: Agent, agents: AgentRegistryPort): boolean {
  if (agent.session.header.origin === "subagent") return true;
  const parentId = agent.session.header.parentSession;
  if (parentId === undefined) return false;
  const parent = agents.lookup(parentId);
  if (!parent.found) return false;
  return agents.isOwnedBy(agent.id, parent.agent);
}

/** `reason.kind` 的运行时取值；拿不到字符串就按空值处理。 */
function readTurnKind(reason: TurnEndReason): string {
  const kind: string = reason.kind;
  return typeof kind === "string" ? kind : "";
}

/**
 * dsh-notifier events 域 —— agent 状态机：完成判定与 turn 去重（装配与卸载成对）。
 * 常驻状态：每个 agent 的运行足迹、最近一次 turn/end、已发过的 turn。
 */
import type { Agent } from "@deepseek-ai/dsh-agent";
import type { AgentStatusPayload, AgentTurnStoppingPayload } from "../../deps.ts";
import { isSubagentOf, lastTurnEndOf, sessionTitleOf } from "../session/index.ts";
import type { TurnEndEvidence } from "../session/type.ts";
import type {
  AgentRun,
  DoneOutcome,
  StateDeps,
  TurnEvidence,
  TurnStoppingOutcome,
} from "./type.ts";

const NOT_INSTALLED = "dsh-notifier: events 域状态机尚未装配";

/** 未装配时的占位：真被读到说明装配守卫有洞，当场暴露而不是按空状态判定；日志没人听，静默。 */
const UNINSTALLED: StateDeps = {
  logger: { warn: () => {} },
  agents: {
    lookup: () => {
      throw new Error(NOT_INSTALLED);
    },
    isOwnedBy: () => {
      throw new Error(NOT_INSTALLED);
    },
  },
};

/** 完成判定与 turn 去重的状态机。 */
class AgentStateMachine {
  private installed = false;
  private deps: StateDeps = UNINSTALLED;
  private readonly runs = new Map<string, AgentRun>();
  /** 键是 agent id，也就是会话 id：`session/event` 只给得到会话 id。 */
  private readonly turnEnds = new Map<string, TurnEndEvidence>();
  private readonly notifiedTurns = new Set<string>();

  /** 装配：重复装配是编程错误。 */
  install(deps: StateDeps): void {
    if (this.installed) throw new Error("dsh-notifier: events 域状态机只能装配一次");
    this.installed = true;
    this.deps = deps;
  }

  /** 卸载：清掉全部状态与集合，并复位装配标记——同进程的下一次装配不能撞上「只能装配一次」。 */
  release(): void {
    this.runs.clear();
    this.turnEnds.clear();
    this.notifiedTurns.clear();
    this.deps = UNINSTALLED;
    this.installed = false;
  }

  /** 记下一次推送来的 `turn/end`（idle 判定优先用它）。 */
  rememberTurnEnd(agentId: string, evidence: TurnEndEvidence): void {
    this.turnEnds.set(agentId, evidence);
  }

  /** agent 生命周期迁移：running 起记，idle 判定完成。 */
  observeStatus(payload: AgentStatusPayload): DoneOutcome {
    const agent = payload.agent;
    const run = this.runOf(agent.id);
    if (payload.status === "idle" && run.runningSeen) return this.settleIdle(agent, run);
    if (payload.status === "running") this.markRunning(agent, run);
    return { ok: false };
  }

  /** turn 到停止边界：同一 agent 的同一 turn 只放行一次。 */
  observeTurnStopping(payload: AgentTurnStoppingPayload): TurnStoppingOutcome {
    const turn = payload.turn;
    const key = `${payload.agent.id}:${Number.isFinite(turn) ? turn : "?"}`;
    if (this.notifiedTurns.has(key)) return { ok: false };
    this.notifiedTurns.add(key);
    const title = sessionTitleOf(payload.agent);
    return {
      ok: true,
      turn: Number.isFinite(turn) ? turn : undefined,
      taskTitle: title.found ? title.title : undefined,
    };
  }

  /** agent 消亡：清掉它的运行足迹、turn 证据与去重记录（不产出请求）。 */
  forget(agentId: string): void {
    this.runs.delete(agentId);
    this.turnEnds.delete(agentId);
    for (const key of [...this.notifiedTurns]) {
      if (key.startsWith(`${agentId}:`)) this.notifiedTurns.delete(key);
    }
  }

  private runOf(agentId: string): AgentRun {
    const existing = this.runs.get(agentId);
    if (existing !== undefined) return existing;
    const run: AgentRun = { runningSeen: false, startedAt: 0 };
    this.runs.set(agentId, run);
    return run;
  }

  private markRunning(agent: Agent, run: AgentRun): void {
    run.runningSeen = true;
    run.startedAt = Date.now();
    const baseline = lastTurnEndOf(agent);
    run.runningBaseline = baseline.found ? baseline.evidence : undefined;
  }

  private settleIdle(agent: Agent, run: AgentRun): DoneOutcome {
    const durationMs = run.startedAt > 0 ? Date.now() - run.startedAt : 0;
    run.runningSeen = false;
    run.startedAt = 0;

    const evidence = this.resolveEvidence(agent, run);
    const best = evidence.best;
    // 没产出通知的这一轮同样记账：否则 abort 之后同一 turn 的旧证据会在下一次 idle 被当成新完成。
    if (best !== undefined) run.lastEndedTurn = best.turn;
    if (best === undefined || !evidence.hasNewEnd || best.kind !== "completed") {
      this.warnIdleSkipped(agent.id, evidence);
      return { ok: false };
    }
    const title = sessionTitleOf(agent);
    return {
      ok: true,
      kind: isSubagentOf(agent, this.deps.agents) ? "subagent-done" : "done",
      taskTitle: title.found ? title.title : undefined,
      durationMs,
    };
  }

  /** 推送证据优先、快照兜底；不比进入 running 时更新的快照是上一轮的（冻结）。 */
  private resolveEvidence(agent: Agent, run: AgentRun): TurnEvidence {
    const streamed = this.turnEnds.get(agent.id);
    const pushed = streamed !== undefined && Number.isFinite(streamed.turn) ? streamed : undefined;
    const read = pushed === undefined ? lastTurnEndOf(agent) : undefined;
    const snapshot = read !== undefined && read.found ? read.evidence : undefined;
    const baselineTurn = run.runningBaseline?.turn;
    const stale =
      pushed === undefined &&
      snapshot !== undefined &&
      baselineTurn !== undefined &&
      snapshot.turn <= baselineTurn;
    const best = pushed ?? (stale ? undefined : snapshot);
    const rememberedTurn = run.lastEndedTurn;
    return {
      best,
      snapshot,
      pushed,
      source: evidenceSourceOf(stale, pushed, snapshot),
      rememberedTurn,
      hasNewEnd: best !== undefined && (rememberedTurn === undefined || best.turn > rememberedTurn),
    };
  }

  /** 完成判定跳过时的诊断——「为什么没发 done」的唯一线索；文本与旧实现逐字一致。 */
  private warnIdleSkipped(agentId: string, evidence: TurnEvidence): void {
    const { best, snapshot, pushed, source, rememberedTurn } = evidence;
    this.deps.logger.warn(
      `dsh-notifier: 完成判定跳过（不发 done）agent=${agentId} kind=${best !== undefined ? best.kind : "none"} ` +
        `证据源=${source} 快照turn=${snapshot !== undefined ? String(snapshot.turn) : "-"} ` +
        `推送turn=${pushed !== undefined ? String(pushed.turn) : "-"} ` +
        `记忆turn=${rememberedTurn !== undefined ? String(rememberedTurn) : "-"}`,
    );
  }
}

/** 证据源标签：推送优先，其次快照（比基线旧的快照属于上一轮），都没有就是「无」。 */
function evidenceSourceOf(
  stale: boolean,
  pushed?: TurnEndEvidence,
  snapshot?: TurnEndEvidence,
): string {
  if (pushed !== undefined) return "push";
  if (snapshot === undefined) return "无";
  return stale ? "快照冻结" : "快照兜底";
}

/** 本域唯一的状态机实例：类不外放，外面 `new` 不出第二份。 */
export const agentStates = new AgentStateMachine();

/**
 * dsh-notifier events 域 —— 通知文案单表（本域翻得出来的 6 个内置 kind），标题与正文逐字沿用旧实现。
 * `test` 不在这里：它不对应任何宿主事件，文案归唯一产出方（api 域的测试端点）。
 */
import type { KindText, NotifyDetail } from "./type.ts";

/** 毫秒 → 人类可读耗时（如 "45 秒" / "2 分 15 秒" / "1 小时 2 分 5 秒"）。
 *  导出是为了让这条口径可表驱动：它的产物是纯字符串，走宿主事件断言要造一整条事件链。 */
export function formatDuration(ms: number): string {
  const totalSeconds = Math.max(0, Math.round(Number(ms) / 1000));
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  const parts: string[] = [];
  if (hours > 0) parts.push(`${hours} 小时`);
  if (minutes > 0) parts.push(`${minutes} 分`);
  if (seconds > 0 || parts.length === 0) parts.push(`${seconds} 秒`);
  return parts.join(" ");
}

/** 常见工具名 → 中文可读名（用用户看得懂的动作描述，而不是内部标识）。 */
const TOOL_LABELS: Record<string, string> = {
  pwsh: "PowerShell 命令",
  bash: "终端命令",
  web_search: "联网搜索",
  read: "读取文件",
  write: "写入文件",
  edit: "编辑文件",
  grep: "搜索文件内容",
  glob: "查找文件",
  subagent: "子代理任务",
  subagent_fork: "子代理任务",
  ssh_exec: "SSH 远程执行",
  ssh_upload: "SSH 上传文件",
  ssh_download: "SSH 下载文件",
  ssh_tunnel: "SSH 端口转发",
  ssh_cluster: "SSH 集群执行",
  ask_user_question: "向你提问",
  todo_write: "更新任务清单",
  job_list: "查看后台任务",
  job_output: "查看任务输出",
  job_kill: "停止后台任务",
  workflow: "工作流编排",
  ralph: "Ralph 循环执行",
  memory_add: "写入项目记忆",
  memory_search: "检索项目记忆",
  skill: "加载技能",
  create_goal: "创建目标",
  get_goal: "查看目标",
  update_goal: "更新目标",
};

/**
 * 工具名美化：常见工具查上表；`mcp__server__tool` 展开成「MCP 服务器 "server" 的工具 "tool"」；
 * 其余原样。导出是为了让映射表可表驱动：它不是事件的产物，而是文案口径。
 */
export function prettyToolName(name?: string): string {
  const text = name ?? "?";
  if (Object.prototype.hasOwnProperty.call(TOOL_LABELS, text)) return TOOL_LABELS[text];
  const parts = text.split("__");
  if (parts.length >= 3 && parts[0] === "mcp") {
    return `MCP 服务器 "${parts[1]}" 的工具 "${parts.slice(2).join("__")}"`;
  }
  return text;
}

/**
 * kind → 文案单表：杜绝「表 + switch 分支」双份维护的漂移；时间由系统通知呈现，正文不重复时间戳。
 */
export const NOTIFY_KINDS = {
  ask: {
    title: "DSH：等待审批",
    body: (detail: NotifyDetail) => {
      const lines: string[] = [];
      if (detail.taskTitle)
        lines.push(`任务「${detail.taskTitle}」等待审批（工具「${prettyToolName(detail.tool)}」）`);
      else lines.push(`工具「${prettyToolName(detail.tool)}」等待审批`);
      if (detail.reason) lines.push(`理由：${detail.reason}`);
      lines.push("请到 DSH 界面确认或拒绝");
      return lines.join("\n");
    },
  },
  question: {
    title: "DSH：向你提问",
    body: (detail: NotifyDetail) => {
      const lines: string[] = [];
      if (detail.taskTitle) lines.push(`任务「${detail.taskTitle}」需要你回答`);
      else lines.push("有提问需要你回答");
      if (detail.question) lines.push(`问题：${detail.question}`);
      lines.push("请到 DSH 界面回答");
      return lines.join("\n");
    },
  },
  done: {
    title: "DSH：任务完成",
    body: (detail: NotifyDetail) => {
      const lines: string[] = [];
      if (detail.taskTitle) lines.push(`任务「${detail.taskTitle}」已完成`);
      else lines.push("后台任务已完成");
      lines.push(`耗时：${formatDuration(detail.durationMs ?? 0)}`);
      return lines.join("\n");
    },
  },
  "subagent-done": {
    title: "DSH：子任务完成",
    body: (detail: NotifyDetail) => {
      const lines: string[] = [];
      if (detail.taskTitle) lines.push(`子任务「${detail.taskTitle}」已完成`);
      else lines.push("子任务已完成");
      lines.push(`耗时：${formatDuration(detail.durationMs ?? 0)}`);
      return lines.join("\n");
    },
  },
  error: {
    title: "DSH：任务出错",
    body: (detail: NotifyDetail) => {
      const lines: string[] = [];
      if (detail.taskTitle) lines.push(`任务「${detail.taskTitle}」执行出错`);
      else lines.push("任务执行出错");
      if (detail.turn)
        lines.push(
          `第 ${detail.turn} 轮${detail.step ? `第 ${detail.step} 步` : ""}：${detail.message ?? ""}`,
        );
      else if (detail.message) lines.push(`错误：${detail.message}`);
      return lines.join("\n");
    },
  },
  "turn-end": {
    title: "DSH：轮次完成",
    body: (detail: NotifyDetail) => {
      const turn = detail.turn ? `第 ${detail.turn} 轮` : "";
      if (detail.taskTitle) return `任务「${detail.taskTitle}」${turn}工作已完成`;
      return `${turn}工作已完成`;
    },
  },
} satisfies Record<string, KindText>;

/** 表里有的种类，也就是本域翻得出来的那些。 */
export type TranslatedKind = keyof typeof NOTIFY_KINDS;

/**
 * dsh-notifier events 域 —— 宿主事件 → 通知请求；不看开关（那是裁决层的事）。
 * 认不出的宿主事件返回「不是通知」而不是抛错——事件链是活的，抛错等于让插件崩在运行中。
 */
import type { Agent } from "@deepseek-ai/dsh-agent";
import type { SessionEvent } from "@deepseek-ai/dsh-session";
import type { ApprovalRequest } from "@deepseek-ai/dsh-user-approval";
import type { AskUserQuestionRequest } from "@deepseek-ai/dsh-user-questions";
import type {
  AgentDisposedPayload,
  AgentErrorPayload,
  AgentStatusPayload,
  AgentTurnStoppingPayload,
} from "../../deps.ts";
import { sessionTitleOf, turnEndEvidenceOf } from "../session/index.ts";
import type { SessionTitle } from "../session/type.ts";
import { agentStates } from "../state/index.ts";
import { NOTIFY_KINDS } from "./catalog.ts";
import type { TranslatedKind } from "./catalog.ts";
import type { NotifyDetail, Translation } from "./type.ts";

/** 不是通知：多数宿主事件的归宿。 */
const NOT_A_NOTIFICATION: Translation = { ok: false };

/** 把详情渲染成一条请求；标题与正文只来自本目录的文案表（本域不填 severity）。 */
function render(kind: TranslatedKind, detail: NotifyDetail): Translation {
  const text = NOTIFY_KINDS[kind];
  return { ok: true, request: { kind, title: text.title, body: text.body(detail) } };
}

/** 任务名；`agent` 可缺（提问载荷上是可选的），缺了就是没有任务名。 */
function titleOf(agent?: Agent): SessionTitle {
  return agent === undefined ? { found: false } : sessionTitleOf(agent);
}

/** 审批请求 → `ask`（工具名 + 理由 + 任务名）。 */
export function translateApproval(request: ApprovalRequest): Translation {
  const title = titleOf(request.agent);
  return render("ask", {
    tool: request.toolName,
    taskTitle: title.found ? title.title : undefined,
    reason: request.reason,
  });
}

/** 用户提问 → `question`（首问摘要 + 任务名）。 */
export function translateUserQuestion(request: AskUserQuestionRequest): Translation {
  const first = request.questions[0];
  const title = titleOf(request.agent);
  return render("question", {
    taskTitle: title.found ? title.title : undefined,
    question: first !== undefined && first.question.length > 0 ? first.question : undefined,
  });
}

/** 会话内事件 → 通知请求：只认 `turn/end`，只记账不产出。 */
export function translateSessionEvent(sessionId: string, event: SessionEvent): Translation {
  const read = turnEndEvidenceOf(event);
  if (read.found) agentStates.rememberTurnEnd(sessionId, read.evidence);
  return NOT_A_NOTIFICATION;
}

/** agent 生命周期迁移 → 完成通知；`idle` 是判据，`running` 只记账。 */
export function translateAgentStatus(payload: AgentStatusPayload): Translation {
  const outcome = agentStates.observeStatus(payload);
  if (!outcome.ok) return NOT_A_NOTIFICATION;
  return render(outcome.kind, { taskTitle: outcome.taskTitle, durationMs: outcome.durationMs });
}

/** agent 被销毁 → 清账（不产出：完成与否已由 `idle` 判过）。 */
export function translateAgentDisposed(payload: AgentDisposedPayload): Translation {
  agentStates.forget(payload.agent.id);
  return NOT_A_NOTIFICATION;
}

/** turn 到停止边界 → `turn-end`（同一 turn 只发一次）。 */
export function translateTurnStopping(payload: AgentTurnStoppingPayload): Translation {
  const outcome = agentStates.observeTurnStopping(payload);
  if (!outcome.ok) return NOT_A_NOTIFICATION;
  return render("turn-end", { turn: outcome.turn, taskTitle: outcome.taskTitle });
}

/** agent 出错 → `error`（错误文本 + turn + step + 任务名）。 */
export function translateAgentError(payload: AgentErrorPayload): Translation {
  const title = titleOf(payload.agent);
  return render("error", {
    message: payload.error,
    taskTitle: title.found ? title.title : undefined,
    turn: payload.turn,
    step: payload.step,
  });
}

packages/dsh-notifier/test/integration/r.source:
/**
 * dsh-notifier — 组合根（`src/index.ts`）的真实 cordis Context 集成测试。
 *
 * 面口径：这里测的是**宿主看见的那一面**——`apply` 收窄宿主上下文、按序装配八个域、卸载逆序释放。
 * 这些行为只有放进真实 cordis 才成立：`inject` 门（未就绪不装配）、两条 waterfall 的 `prepend`
 * 链序、`{ global: true }` 的作用域过滤、`ctx.effect` 的卸载时机、`internal/service` 的晚到通知。
 * 假宿主只提供 `webServer`（组合根唯一触碰的宿主服务）与可选的 `settings`；事件总线、落盘、
 * 裁决管线全是真的——**不 mock `@deepseek-ai/cordis`**，也不用 `vi.mock`/`vi.fn`。
 *
 * 落盘隔离（红线）：config / stores / stream 的单例在**模块加载期**就用 `notifierFile()` 定死了
 * 路径，所以必须先把 `DSH_HOME` 指到 `mkdtempSync` 出的临时目录，再用**动态 `import()`** 拉组合根。
 * 写反了本节全部落盘就进真实 `~/.dsh`——那正是正在跑的 `dsh web` 的 home。
 *
 * 写队列纪律：历史与配置的落盘是 fire-and-forget（写队列是模块级字段，`release` 不清它），故每个
 * 产生落盘的用例都要等到自己那一条在磁盘上可见才算完；需要「没有新写入」这类否定判据时，用
 * `stores` 域自己的写口排一次队当**界碑**——队列串行，界碑落盘即此前排队的全部落盘。
 *
 * 时间纪律：本文件不钉系统时钟，`pollUntil` 的 deadline 读的正是 `Date.now()`，钉住它失败会从
 * 「断言红」退化成挂死。`afterEach` 仍还原一次，防将来有人在用例里钉。
 */
import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { afterAll, afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { Context } from "@deepseek-ai/cordis";
import type { Events, Fiber, ThisType as EventThis } from "@deepseek-ai/cordis";
import type { Agent } from "@deepseek-ai/dsh-agent";
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import type { Session, SessionEvent } from "@deepseek-ai/dsh-session";
import type { ApprovalOutcome, ApprovalRequest } from "@deepseek-ai/dsh-user-approval";
import type {
  AskUserQuestionAnswer,
  AskUserQuestionRequest,
} from "@deepseek-ai/dsh-user-questions";

import {
  assertEventReachability,
  assertRealCordisContextSemantics,
} from "../../../../test/smoke-lib.ts";
import { pollUntil, settleMicrotasks, tempDshHome } from "../helpers.ts";

// DSH_HOME 必须先于被测模块求值：三个单例的落盘路径在构造时定下，而静态 import 会在任何语句
// 之前执行——顺序反了，本节全部落盘就写进真实 `~/.dsh`。
const home = tempDshHome();
const notifier = await import("../../src/index.ts");
const apiApi = await import("../../src/server/api/interface.ts");
const configApi = await import("../../src/server/config/interface.ts");
const sdkApi = await import("../../src/server/sdk/interface.ts");
const storesApi = await import("../../src/server/stores/interface.ts");
const sharedApi = await import("../../src/server/shared/interface.ts");

/** 本插件的落盘位置（新布局：包私有目录，见 `shared/paths.ts`）。 */
const storageDir = join(home.dir, "@wingsky-1", "dsh-notifier");
const configFile = sharedApi.notifierFile(sharedApi.CONFIG_FILE_NAME);
const historyFile = sharedApi.notifierFile(sharedApi.HISTORY_FILE_NAME);
const seqFile = sharedApi.notifierFile(sharedApi.SEQ_FILE_NAME);
const versionFile = sharedApi.notifierFile(sharedApi.VERSION_FILE_NAME);

/** 种下的那份配置的原文：否定判据用它比对「一个字节都没动过」。 */
function seededConfig(): string {
  return `${JSON.stringify(BASE_SETTINGS, null, 2)}\n`;
}

/** 宿主契约冻结的 8 条浏览器端点（客户端锁定，独立抄写才守得住改路径）。 */
const ROUTE_PATHS: readonly string[] = [
  "/api/dsh-notifier/config",
  "/api/dsh-notifier/history",
  "/api/dsh-notifier/status",
  "/api/dsh-notifier/kinds",
  "/api/dsh-notifier/test",
  "/api/dsh-notifier/health",
  "/api/dsh-notifier/diagnostics",
  "/api/dsh-notifier/events",
];

/**
 * 基础设置：系统出口整个关掉、浏览器出口只弹不响。
 *
 * 系统出口在 Linux 会真的 spawn `notify-send`——测试不该在开发机上弹通知；浏览器出口的帧则
 * 经组合根的 `FrameBus` 进 api 域的流（只写 `seq.json`），是本文件观察「帧走出去了」的唯一手段。
 * 两条内置频道的形态**显式写出来**：`enabled` 是频道唯一的投递闸门，靠 `systemNotify:false`
 * 之类的弹窗键关不掉它（那只让出口无事可做，仍会留下一条 skipped 明细）。
 * `historyMaxAgeDays` 取**非默认值**：逆序释放那条判据要一个与默认值不同的可辨读数。
 */
const BASE_SETTINGS = {
  channels: [
    {
      type: "browser",
      id: "browser",
      enabled: true,
      popup: true,
      sound: false,
      whenVisible: false,
    },
    { type: "system", id: "system", enabled: false, popup: false, sound: false },
  ],
  historyMaxAgeDays: 7,
} as const;

/** 历史行：只取本文件当判据的字段（整体比较会把域内文案变化变成假红）。 */
interface HistoryLine {
  kind?: string;
  message?: string;
  suppressed?: string;
  channels?: ReadonlyArray<{ channelId: string; status: string }>;
}

/** 磁盘上的历史记录。 */
function historyLines(): HistoryLine[] {
  let text: string;
  try {
    text = readFileSync(historyFile, "utf8");
  } catch {
    return [];
  }
  return text
    .split("\n")
    .filter(Boolean)
    .flatMap((line) => {
      try {
        return [JSON.parse(line) as HistoryLine];
      } catch {
        // 坏行不当判据，也不吞掉同行之外的记录
        return [];
      }
    });
}

/** 某一种通知落了几条。 */
function countKind(kind: string): number {
  return historyLines().filter((line) => line.kind === kind).length;
}

/** 磁盘上第一条某一种通知：`beforeEach` 清过历史，所以不受上一个用例干扰。 */
function kindLine(kind: string): HistoryLine | undefined {
  return historyLines().find((line) => line.kind === kind);
}

/** 界碑用的种类名：只出现在界碑行里，任何通知判据都不会撞上它。 */
const SENTINEL_KIND = "itest-sentinel";

/**
 * 排一次界碑并等它落盘，用来给**否定**判据划界。
 *
 * 写队列串行，界碑在磁盘上可见即此前排队的写入全部落盘；没有界碑的「没有新记录」只是抢跑得来的
 * ——它证明的是「还没写完」，不是「不会写」。
 */
async function settleHistory(): Promise<void> {
  storesApi.appendHistory({ ts: Date.now(), kind: SENTINEL_KIND, title: "界碑", message: "-" });
  await pollUntil(() => historyLines().some((line) => line.kind === SENTINEL_KIND), "界碑落盘");
}

/** 浏览器出口的序号：`seq.json` 前进一格 = 帧真的走完了 FrameBus → api 域 → 流。 */
function seqValue(): number {
  try {
    const parsed = Number.parseInt(readFileSync(seqFile, "utf8").trim(), 10);
    return Number.isFinite(parsed) ? parsed : 0;
  } catch {
    return 0;
  }
}

/**
 * 本用例的序号锚点（每轮 +1000）。
 *
 * 序号是 fire-and-forget 写，「等于锚点 +1」这类判据要挡得住上一个用例迟到的那一笔——递增的锚点
 * 让迟到的值必然小于本轮的起点，于是「文件里出现了本轮的格子」只可能由本轮自己的广播产生。
 */
let seqAnchor = 0;

function seedSeqAnchor(): void {
  seqAnchor += 1000;
  mkdirSync(dirname(seqFile), { recursive: true });
  writeFileSync(seqFile, `${seqAnchor}\n`);
}

/** 写一份设置文件（组合根装配时同步读它，故必须用同步写）。 */
function seed(settings: Record<string, unknown>): void {
  mkdirSync(dirname(configFile), { recursive: true });
  writeFileSync(configFile, `${JSON.stringify(settings, null, 2)}\n`);
}

/** 假会话日志条目：本块只读 `type` 与 `data`（与 events 域单测同一口径）。 */
function turnEndEvent(turn: number, kind: string): SessionEvent {
  return { type: "turn/end", data: { turn, reason: { kind } } } as unknown as SessionEvent;
}

/** 假 agent：只露出 events 域真的会读的几处（`id` 与 `session` 的 header / 日志快照）。 */
function fakeAgent(
  id: string,
  events: SessionEvent[] = [],
  header: Record<string, unknown> = {},
): Agent {
  return {
    id,
    session: { header, snapshotEvents: () => events },
  } as unknown as Agent;
}

/** 假会话：`session/event` 的载荷带整份会话对象，而本插件只用它的 `id`。 */
function fakeSession(id: string): Session {
  return { id } as unknown as Session;
}

/**
 * 宿主按作用域派发时传的 `this`：`agent/*` 声明的是 `Scoped<Agent>`、`session/event` 是
 * `Scoped<Session>`，而那个 brand 不是本包的依赖，故从事件签名上取 `this` 位。测试要造的正是
 * `{ [Context.filter]: … }` 这一个成员——直接抄 `Scoped<…>` 会把它变成第二份事实源。
 */
type ScopedThis<K extends keyof Events> = EventThis<Events[K]>;

/** 作用域收紧的派发载体：filter 恒假，于是**只有** `{ global: true }` 的订阅能收到。 */
function scopeRejecting<K extends keyof Events>(): ScopedThis<K> {
  return { [Context.filter]: () => false } as unknown as ScopedThis<K>;
}

/**
 * 假 settings 服务只提供 describe 低优先级兜底；正式历史来源由 upgrade 域直接读取 DSH_HOME 双文件。
 * `describe()` 在真实宿主里只列**已注册**的命名空间，所以这里的 `user` 用三种取值对应三种真实形态：
 * `undefined` = 没注册这条命名空间（新架构的常态，服务面读不到）；`{}` = 注册了但 user 层为空；有键 = 注册且用户设过。
 */
function fakeSettings(user: Record<string, unknown> | undefined): { describe: () => unknown[] } {
  return {
    describe: () => (user === undefined ? [] : [{ ns: "dsh-notifier", user }]),
  };
}

/**
 * 假宿主 webServer：只实现组合根够得着的那一面（`register`），并记下摘除时的现场。
 *
 * `failAt` 让第 N 条摘除器抛错——宿主摘路由失败是真实会发生的（路由已被别人摘掉、宿主换实现），
 * 组合根的释放壳对它的承诺是「不阻断其余」。
 */
function fakeWebServer(
  observe: () => { configDays: number; serviceAlive: boolean },
  options: { failAt?: number } = {},
) {
  const routes: WebRoute[] = [];
  const removals: Array<{ path: string; configDays: number; serviceAlive: boolean }> = [];
  const service = {
    register(route: WebRoute) {
      routes.push(route);
      return () => {
        removals.push({ path: route.path, ...observe() });
        if (removals.length === options.failAt) throw new Error(`摘除失败：${route.path}`);
      };
    },
  } as unknown as Context["webServer"];
  return { service, routes, removals };
}

/** 假宿主 agent 注册表：只实现组合根读的两处（`get` 与 `isOwnedBy`）。 */
function fakeAgents(parent: Agent, child: Agent): Context["agents"] {
  return {
    get: (id: string) => (id === parent.id ? parent : undefined),
    isOwnedBy: (id: string, owner: Agent) => id === child.id && owner === parent,
  } as unknown as Context["agents"];
}

/**
 * 日志出口：`LoggerService` 的公开扩展点，用它把 warn 收进数组。
 *
 * 为什么不读内置的 `ctx.logger.buffer`：那个出口的阈值是 INFO，warn（级别 2）落在它之外，
 * buffer 里永远看不到本文件的判据文案。阈值按 `levels.default` 给——它是出口自己的约定。
 */
function captureWarnings(root: Context): string[] {
  const warnings: string[] = [];
  root.logger.exporter({
    levels: { default: 2 },
    export: (message) => {
      if (message.type === "warn") warnings.push(String(message.args[0]));
    },
  });
  return warnings;
}

/** 一次挂载的全部观测物。 */
interface Mounted {
  readonly root: Context;
  readonly fiber: Fiber;
  readonly host: ReturnType<typeof fakeWebServer>;
  /** 宿主日志出口收到的 warn 文案（组合根只经它报错）。 */
  readonly warns: string[];
  unmount(): Promise<void>;
}

/** 已挂载但用例没显式卸载的实例：`afterEach` 兜底收掉，免得路由/心跳漏到下一个用例。 */
let live: Fiber | null = null;

/**
 * 按宿主的真实挂载顺序装配：先 provide 宿主服务，再 `ctx.plugin(插件)`。
 *
 * `settings` 是本插件的**显式依赖**（组合根的 `inject`）：宿主保证它在插件装配前就绪，所以这里
 * 总是先 provide 一个假的；`settings` 的值就是那份 0.2.3 存量命名空间的 user 层（缺省 = 有服务
 * 但没存量）。「服务没来」这条分支已不属于本插件——它变成 cordis 的 inject 门（见 inject 门用例）。
 * `services` 是其余宿主服务（如 `agents`）——装与不装是两条不同的判定路径。
 */
async function mount(options: {
  config?: { enabled?: boolean };
  settings?: Record<string, unknown>;
  services?: Record<string, unknown>;
}): Promise<Mounted> {
  const root = new Context();
  root.provide("settings", fakeSettings(options.settings));
  for (const [name, value] of Object.entries(options.services ?? {})) root.provide(name, value);
  const warns = captureWarnings(root);
  const host = fakeWebServer(() => ({
    configDays: configApi.readConfig().historyMaxAgeDays,
    serviceAlive: root.get("wingsky.notifier", false) !== undefined,
  }));
  root.provide("webServer", host.service);
  const fiber = await root.plugin(notifier, options.config);
  live = fiber;
  return {
    root,
    fiber,
    host,
    warns,
    unmount: async () => {
      live = null;
      await fiber.dispose();
    },
  };
}

/**
 * 模拟宿主内置 answerer：链上**更早注册**的那一个，它给出的判定就是这次请求的最终结果。
 * 它不调 `next()`——宿主自己的应答者拿到判定后即短路，这正是本插件必须 prepend 的理由。
 */
async function mountApprovalAnswerer(
  root: Context,
  calls: string[],
  outcome: ApprovalOutcome,
): Promise<Fiber> {
  return root.plugin((ctx) => {
    ctx.on("approval/request", () => {
      calls.push("answerer");
      return Promise.resolve(outcome);
    });
  });
}

/** 同上，提问那条链上的 answerer（两条 waterfall 同构，夹具分开写以免一条覆盖另一条）。 */
async function mountQuestionAnswerer(
  root: Context,
  calls: string[],
  answer: AskUserQuestionAnswer,
): Promise<Fiber> {
  return root.plugin((ctx) => {
    ctx.on("user-questions/request", () => {
      calls.push("answerer");
      return Promise.resolve(answer);
    });
  });
}

beforeEach(() => {
  // 单例的落盘路径跨用例不变，能重置的只有文件：不重置的话上一个用例的配置/历史就是本用例的起点。
  rmSync(historyFile, { force: true });
  rmSync(configFile, { force: true });
  // 正式历史来源也落在这个共享的临时 DSH_HOME 里；清掉双文件，避免上个用例的存量进入下个用例。
  rmSync(join(home.dir, "settings.yaml.imported"), { force: true });
  rmSync(join(home.dir, "settings.yaml"), { force: true });
  seedSeqAnchor();
  seed(BASE_SETTINGS);
});

afterEach(async () => {
  vi.useRealTimers();
  if (live) {
    const fiber = live;
    live = null;
    await fiber.dispose();
  }
  // api 域的装配标记只在它自己的 release() 走完时才复位，而有一条用例刻意让摘除器抛错把它停在
  // 半释放（那是它的判据）。这里无条件补一次收尾：域释放幂等，正常用例上是空转——不放在用例里
  // 是因为用例前面任何一条断言红了就会跳过补偿，后续用例会级联红成一片。
  apiApi.releaseApi();
});

afterAll(() => {
  home.dispose();
});

describe("装配与暴露", () => {
  it("装配即暴露：服务面挂在宿主上下文上（声明合并的读法可用），登记与发送当场可用", async () => {
    const { root, fiber, unmount } = await mount({});
    // 声明合并的读法可用，而且读到的是**同一个**对象：服务面经 `ctx.provide` 挂在宿主上下文上，
    // 不是又造了一份（再造一份就会有两个 apiVersion、两套登记表）。
    const service = root.get("wingsky.notifier", false);
    expect(fiber.ctx["wingsky.notifier"]).toBe(service);
    expect(service?.apiVersion).toBe(2);
    // 管理面（清单 / 确认）不进服务面：多给一样，兄弟插件就能替用户放行自己的通知种类。
    expect("confirmKind" in (service ?? {})).toBe(false);

    service?.registerKind({ id: "itest:face", label: "集成测试" });
    expect(sdkApi.listKinds()).toContainEqual({
      id: "itest:face",
      label: "集成测试",
      confirmed: false,
    });
    // 未确认的外部种类：送进的是真管线，出去的是一条「unlisted」归档（不是静默丢弃）。
    await service?.send({ kind: "itest:face", body: "正文" });
    await pollUntil(() => countKind("itest:face") === 1, "登记后的发送落史");
    expect(kindLine("itest:face")?.suppressed).toBe("unlisted");

    await unmount();
    // 卸载后消费方按「通知中心不在」降级：`get` 拿空而不是拿到半死对象。
    expect(root.get("wingsky.notifier", false)).toBeUndefined();
  });

  it("inject 门：两条宿主服务（webServer / settings）都就绪才装配，缺一条都不跑", async () => {
    const root = new Context();
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }));
    const fiber = await root.plugin(notifier);
    live = fiber;

    // 缺依赖时的现场：插件没跑（路由为空、服务面没上），也没有装配失败的声音。
    expect(host.routes).toHaveLength(0);
    expect(root.get("wingsky.notifier", false)).toBeUndefined();

    // 只补一条还不够：settings 是显式依赖（存量配置的读取面），缺它时装配体一步都不该走。
    root.provide("webServer", host.service);
    await settleMicrotasks();
    expect(host.routes).toHaveLength(0);
    expect(root.get("wingsky.notifier", false)).toBeUndefined();

    root.provide("settings", fakeSettings({}));
    await fiber.await();
    expect(host.routes.map((route) => route.path)).toHaveLength(8);
    expect(root.get("wingsky.notifier", false)?.apiVersion).toBe(2);
  });

  /**
   * 宿主契约 canary——**不是本插件的判据**：两个共用 helper 都只在自己临时挂的监听器上断言 cordis
   * 的语义（未注入访问抛错 / 缺位 get 安全 / effect 真实清理 / 作用域过滤只放行 global），
   * 它们不触本插件的任何代码。放在一个用例里是因为两者共用同一次装配，判据互不相干。
   */
  it("宿主契约 canary：真实 Context 语义 + `{global:true}` 的作用域过滤语义（非本插件行为判据）", async () => {
    const { fiber, unmount } = await mount({});
    // 插件 fiber 的运行时上下文才是「真实」的那一份：root 语义下未注入访问会静默给 undefined，
    // 断言①在那里恒真——历史教训（根因 A：fake-ctx 把服务当普通属性注入）正是靠这条堵住的。
    // 断恒等而非断存在：`root.fiber` 也存在，只有插件 fiber 才带 `runtime`（根为 null）。
    expect(fiber.ctx.fiber).toBe(fiber);
    assertRealCordisContextSemantics(fiber.ctx);
    assertEventReachability(fiber.ctx, Context, "agent/status", {
      agent: fakeAgent("itest-reach"),
      status: "running",
    });
    await unmount();
  });

  it("挂载点总开关 enabled:false 抵达裁决层：请求照进管线，但记的是 disabled 而不是照常投递", async () => {
    const { root, unmount } = await mount({ config: { enabled: false } });
    root.emit("agent/error", {
      agent: fakeAgent("itest-disabled"),
      turn: 1,
      step: 1,
      error: new Error("炸了"),
    });
    await pollUntil(() => countKind("error") === 1, "总开关关闭时的归档");
    expect(kindLine("error")?.suppressed).toBe("disabled");
    // 关掉的是「投递」，不是「记录」：帧的写排在归档之前，归档已在磁盘上时序号若前进过就已可见
    // ——所以这里断「没走到下一格」而不是「等于锚点」，免得受上一个用例迟到的那一笔影响。
    expect(seqValue()).not.toBe(seqAnchor + 1);
    await unmount();
  });
});

